from lib import Q
C='artificial-nails'
Q(C,'basic',"아크릴 네일을 만들 때 섞어 쓰는 두 가지 재료는?","리퀴드(모노머)와 파우더(폴리머)",[("젤과 젤 클렌저","젤 네일 재료입니다."),("글루와 랩","랩 네일 재료입니다."),("베이스 코트와 톱 코트","폴리시 컬러링 재료입니다.")],"아크릴 = 리퀴드(모노머) + 파우더(폴리머)","**아크릴 네일**은 아크릴 **리퀴드(모노머)**에 브러시를 적셔 **파우더(폴리머)**를 묻혀 만든 볼을 손톱에 올려 모양을 만듭니다. 리퀴드와 파우더가 반응해 단단하게 굳습니다.",5,["아크릴 네일"])
Q(C,'basic',"스컬프처 네일을 만들 때 프리에지 아래에 끼워 인조 네일의 길이를 만드는 받침이 되는 것은?","네일 폼",[("네일 팁","팁 위드 파우더·랩에 쓰는 미리 만들어진 인조 손톱입니다."),("오렌지우드스틱","잔여물 정리 등에 쓰는 나무 막대입니다."),("핑거볼","큐티클을 불리는 그릇입니다.")],"스컬프처 길이 받침 = 네일 폼","**스컬프처**는 팁을 붙이지 않고 **네일 폼**을 프리에지 아래에 끼워 받침으로 삼고, 그 위에 아크릴이나 젤을 올려 길이를 만드는 방법입니다.",5,["스컬프처"])
Q(C,'intermediate',"네일 팁의 크기를 고르는 방법으로 가장 알맞은 것은?","자연 네일의 폭과 같거나 조금 큰 것을 고른다",[("자연 네일보다 많이 작은 것을 골라 끼운다","작은 팁은 양옆이 들뜨고 갈라집니다."),("모든 손가락에 같은 크기를 쓴다","손가락마다 손톱 폭이 달라 각각 맞춥니다."),("자연 네일보다 두 배 넓은 것을 고른다","너무 크면 옆 피부에 닿고 모양이 어색합니다.")],"팁 크기 = 자연 네일 폭과 같거나 조금 크게","네일 팁은 손가락마다 **자연 네일의 폭과 같거나 조금 큰** 것을 고르고, 필요하면 양옆을 파일로 다듬어 맞춥니다. 작은 팁은 들뜨거나 갈라질 수 있습니다.",4,["네일 팁"])
Q(C,'intermediate',"네일 팁을 붙일 때 팁의 접착 부분(웰)이 자연 네일을 덮는 범위로 알맞은 것은?","자연 네일의 절반을 넘지 않게 한다",[("자연 네일 전체를 덮게 한다","너무 넓게 덮으면 자연 네일이 숨을 쉬듯 보호받지 못하고 들뜸이 생기기 쉽습니다."),("큐티클 위까지 덮게 한다","큐티클이나 피부에 닿으면 들뜨고 자극이 됩니다."),("프리에지 끝에 1mm만 걸치게 한다","너무 좁으면 잘 떨어집니다.")],"팁 접착 = 자연 네일의 1/2 이내","팁의 접착 부분(웰)은 **자연 네일의 절반을 넘지 않게** 붙입니다. 붙인 뒤에는 자연 네일과 팁 사이의 턱을 파일로 매끄럽게 없앱니다.",4,["네일 팁"])
Q(C,'basic',"팁을 붙인 뒤 자연 네일과 팁이 만나는 부분에 생긴 턱을 처리하는 방법은?","파일로 갈아 매끄럽게 이어지게 한다",[("턱을 그대로 두고 컬러를 바른다","턱이 보이고 들뜨는 원인이 됩니다."),("니퍼로 턱을 잘라 낸다","니퍼로 자르면 팁이 깨질 수 있습니다."),("큐티클 오일을 발라 숨긴다","오일은 턱을 없애지 못하고 접착을 방해합니다.")],"팁 턱 = 파일로 매끄럽게","팁을 붙이면 자연 네일과 팁 사이에 **턱**이 생깁니다. 자연 네일을 상하게 하지 않도록 조심하며 **파일로 턱만 갈아** 매끄럽게 이어지게 합니다.",4,["네일 팁"])
Q(C,'intermediate',"팁 위드 파우더에서 팁 위에 글루를 바르고 뿌려서 두께와 강도를 만드는 재료는?","필러 파우더",[("젤 클렌저","젤 표면의 미경화 젤을 닦는 제품입니다."),("큐티클 오일","보습 제품입니다."),("베이스 코트","컬러링의 첫 코팅입니다.")],"팁 위드 파우더 = 팁 + 글루 + 필러 파우더","**팁 위드 파우더**는 팁을 붙인 뒤 **글루**를 바르고 **필러 파우더**를 뿌리는 과정을 반복해 두께와 강도를 만드는 방법입니다.",4,["팁 위드 파우더"])
Q(C,'intermediate',"네일 랩의 재료 가운데 가장 두껍고 튼튼하지만 투명도가 낮아 컬러를 발라야 하는 것은?","린넨",[("실크","얇고 부드러우며 투명해 자연스럽습니다."),("화이버글라스","가는 유리 섬유로 얇고 투명한 편입니다."),("페이퍼","얇고 약해 임시로 씁니다.")],"랩 중 가장 두껍고 튼튼 = 린넨","네일 랩 재료에는 실크, 린넨, 화이버글라스, 페이퍼 등이 있습니다. **린넨**은 가장 두껍고 튼튼하지만 비쳐 보이지 않아 컬러를 발라 마무리합니다.",4,["랩 네일"])
Q(C,'intermediate',"랩 네일이나 팁 작업에서 글루를 빨리 굳게 하려고 뿌리는 제품은?","글루 드라이(액티베이터)",[("프라이머","인조 네일의 접착을 돕는 산성 제품입니다."),("젤 클렌저","미경화 젤을 닦는 제품입니다."),("큐티클 리무버","큐티클을 부드럽게 하는 제품입니다.")],"글루 빨리 굳힘 = 글루 드라이(액티베이터)","**글루 드라이(액티베이터)**는 글루 위에 뿌려 빨리 굳게 하는 제품입니다. 가까이서 많이 뿌리면 열이 날 수 있어 적당한 거리에서 뿌립니다.",3,["랩 네일"])
Q(C,'advanced',"인조 네일에서 힘을 많이 받아 잘 깨지므로 두께를 보강해야 하는, 자연 네일의 프리에지가 시작되는 양옆 부분을 뜻하는 말은?","스트레스 포인트",[("하이포인트(아펙스)","인조 네일에서 가장 높은 곳입니다."),("스마일 라인","프렌치의 경계선입니다."),("C커브","프리에지 단면의 곡선입니다.")],"잘 깨지는 곳 = 스트레스 포인트","**스트레스 포인트**는 자연 네일이 네일 베드에서 떨어져 프리에지가 시작되는 양옆 부분으로, 인조 네일에서 힘을 많이 받아 잘 깨집니다. 이 부분이 너무 얇지 않게 만듭니다.",4,["인조 네일 구조"])
Q(C,'intermediate',"인조 네일을 옆에서 보았을 때 가장 높게 솟은 부분으로, 강도를 주기 위해 만드는 곳은?","하이포인트(아펙스)",[("스트레스 포인트","잘 깨지는 프리에지 시작 부분입니다."),("큐티클 라인","손톱 뿌리 쪽 경계입니다."),("프리에지","손톱 끝부분입니다.")],"가장 높은 곳 = 하이포인트(아펙스)","인조 네일을 옆에서 보면 가장 높게 솟은 곳을 **하이포인트(아펙스)**라 합니다. 이곳에 알맞은 두께를 주어 인조 네일이 튼튼해지게 합니다.",4,["인조 네일 구조"])
Q(C,'intermediate',"인조 네일을 손끝 정면에서 보았을 때 프리에지가 이루는 반원 모양의 곡선을 뜻하는 말은?","C커브",[("스마일 라인","프렌치의 앞쪽 경계선입니다."),("하이포인트","옆에서 본 가장 높은 곳입니다."),("사이드 스트레이트","옆선이 곧게 뻗은 것을 뜻합니다.")],"정면에서 본 반원 곡선 = C커브","**C커브**는 손끝 정면에서 본 프리에지의 반원 모양 곡선입니다. 알맞은 C커브는 인조 네일을 튼튼하게 하고 모양을 자연스럽게 합니다.",4,["인조 네일 구조"])
Q(C,'basic',"아크릴 프렌치 스컬프처에서 프리에지 부분의 하얀 색을 만드는 재료는?","화이트 아크릴 파우더",[("클리어 젤","투명한 젤입니다."),("핑크 폴리시","폴리시는 아크릴 재료가 아닙니다."),("젤 클렌저","미경화 젤을 닦는 제품입니다.")],"아크릴 프렌치 = 화이트 파우더로 스마일 라인","**아크릴 프렌치 스컬프처**는 네일 폼 위에 **화이트 아크릴 파우더**로 프리에지와 스마일 라인을 만들고, 그 뒤 클리어나 핑크 파우더로 네일 바디를 덮습니다.",4,["아크릴 네일"])
Q(C,'intermediate',"인조 네일을 한 뒤 손톱이 자라 큐티클 쪽에 생긴 빈 부분을 화장물로 채워 보수하는 작업은?","필인(fill-in)",[("오프(제거)","인조 네일을 모두 없애는 작업입니다."),("팁 커팅","팁의 길이를 자르는 작업입니다."),("프렌치","프리에지에 색을 칠하는 컬러링입니다.")],"자라난 부분 채우기 = 필인","손톱이 자라면 큐티클 쪽에 인조 네일이 없는 부분이 생깁니다. 들뜬 부분을 정리하고 그 자리에 화장물을 채워 넣는 보수 작업을 **필인(fill-in)**이라 합니다.",4,["인조 네일 보수"])
Q(C,'advanced',"인조 네일이 자연 네일에서 들뜨는(리프팅) 원인으로 거리가 먼 것은?","전 처리로 유분기와 잔여물을 깨끗이 없앴다",[("큐티클이 남은 채 화장물을 올렸다","들뜸의 원인입니다."),("화장물이 피부에 닿았다","들뜸의 원인입니다."),("손톱 표면에 유분이 남아 있었다","들뜸의 원인입니다.")],"들뜸 원인 = 유분·큐티클·피부 접촉 등","인조 네일이 들뜨는 원인은 유분·잔여물이 남아 있거나, 큐티클 위에 화장물을 올렸거나, 화장물이 피부에 닿은 경우 등입니다. 전 처리를 깨끗이 하는 것은 들뜸을 **막는** 방법입니다.",4,["인조 네일 보수"],lock=True)
Q(C,'basic',"얇고 약한 자연 네일 위에 랩·젤·아크릴을 얇게 덮어 길이 연장 없이 튼튼하게 해 주는 작업은?","자연 네일 보강(오버레이)",[("스컬프처","네일 폼으로 길이를 연장하는 작업입니다."),("팁 위드 랩","팁을 붙여 길이를 연장하는 작업입니다."),("필인","자라난 부분을 채우는 보수 작업입니다.")],"얇은 손톱 덮어 튼튼하게 = 자연 네일 보강(오버레이)","**자연 네일 보강(오버레이)**은 길이를 늘리지 않고 자연 네일 위에 랩·젤·아크릴을 얇게 덮어 약한 손톱을 튼튼하게 하는 작업입니다.",4,["자연 네일 보강"])
Q(C,'intermediate',"아크릴 리퀴드(모노머)를 다룰 때 주의 사항으로 가장 알맞은 것은?","피부에 닿지 않게 하고 환기하며, 뚜껑 있는 용기에 조금씩 덜어 쓴다",[("손으로 피부에 발라 흡수시킨다","피부에 닿으면 알레르기와 자극을 일으킬 수 있습니다."),("큰 그릇에 넉넉히 부어 뚜껑 없이 둔다","증기가 퍼지고 불이 붙을 위험이 있습니다."),("창문을 닫고 작업한다","냄새와 증기가 쌓이므로 환기해야 합니다.")],"모노머 = 피부 접촉 금지·환기·조금씩 덜기","아크릴 리퀴드는 피부에 닿으면 **알레르기**와 자극을 일으킬 수 있고 냄새가 강하며 인화성이 있습니다. 피부에 닿지 않게 하고, 환기하며, 디펜디시에 **조금씩 덜어** 씁니다.",4,["아크릴 네일","안전"])
Q(C,'advanced',"젤 원톤 스컬프처 작업의 순서로 가장 알맞은 것은?","전 처리 → 네일 폼 끼우기 → 젤로 길이·모양 만들기 → 경화 → 폼 떼고 파일링 → 마무리",[("네일 폼 끼우기 → 컬러링 → 전 처리 → 경화","전 처리는 맨 처음에 합니다."),("젤 올리기 → 경화 → 네일 폼 끼우기 → 전 처리","네일 폼은 젤을 올리기 전에 끼웁니다."),("파일링 → 젤 클렌저 → 네일 폼 끼우기 → 전 처리","순서가 뒤섞여 있습니다.")],"젤 스컬프처 = 전 처리 → 폼 → 젤 → 경화 → 파일링 → 마무리","젤 원톤 스컬프처는 **전 처리**로 손톱을 준비한 뒤 **네일 폼**을 프리에지 아래에 끼우고, 젤로 길이와 모양을 만들어 **경화**합니다. 폼을 떼어 내고 파일로 모양을 다듬은 뒤 마무리합니다.",3,["젤 네일","스컬프처"])

C='public-health'
Q(C,'basic',"공중보건의 대상으로 알맞은 것은?","지역사회 주민 전체",[("병원에 입원한 환자","개인 환자 치료는 임상 의학의 대상입니다."),("의사와 간호사","공중보건의 대상은 의료인만이 아닙니다."),("감염병 환자만","감염병 환자뿐 아니라 주민 전체가 대상입니다.")],"공중보건 대상 = 지역사회 주민 전체","**공중보건**은 개인이 아니라 **지역사회 주민 전체**를 대상으로 질병을 예방하고 건강을 지키는 활동입니다.",4,["공중보건 기초"])
Q(C,'basic',"감염병이 생기기 위해 필요한 3요소에 해당하지 않는 것은?","치료 약",[("병원체(감염원)","3요소의 하나입니다."),("감염경로(환경)","3요소의 하나입니다."),("숙주의 감수성","3요소의 하나입니다.")],"감염병 3요소 = 감염원·감염경로·숙주의 감수성","감염병이 생기려면 **병원체(감염원)**, **감염경로(환경)**, **숙주의 감수성**이 모두 있어야 합니다. 치료 약은 3요소가 아닙니다.",5,["감염병"],lock=True)
Q(C,'intermediate',"한 나라의 보건 수준을 나타내는 대표적인 지표로 가장 많이 쓰이는 것은?","영아사망률",[("인구 증가율","보건 수준을 직접 나타내는 대표 지표가 아닙니다."),("출생 성비","보건 수준의 대표 지표가 아닙니다."),("국민 1인당 자동차 수","경제 지표입니다.")],"보건 수준 대표 지표 = 영아사망률","**영아사망률**(태어나서 1년이 안 된 아기의 사망 비율)은 환경·영양·의료 수준에 민감해 한 나라의 보건 수준을 나타내는 대표 지표로 쓰입니다.",4,["보건 지표"])
Q(C,'intermediate',"연료가 불완전하게 탈 때 생기며 혈액의 헤모글로빈과 결합해 산소 운반을 막는 기체는?","일산화탄소(CO)",[("이산화탄소(CO₂)","실내 공기 오염의 지표로 쓰이지만 헤모글로빈과 결합해 중독을 일으키는 대표 기체는 아닙니다."),("산소(O₂)","생명 유지에 필요한 기체입니다."),("질소(N₂)","공기의 대부분을 이루는 기체입니다.")],"불완전 연소·헤모글로빈 결합 = 일산화탄소","**일산화탄소**는 불완전 연소로 생기며 산소보다 훨씬 강하게 헤모글로빈과 결합해 몸에 산소가 가지 못하게 합니다. 환기가 중요합니다.",4,["환경보건"])
Q(C,'basic',"모기가 옮기는 감염병은?","말라리아",[("결핵","주로 기침·재채기의 비말로 옮습니다."),("장티푸스","오염된 물과 음식으로 옮습니다."),("파상풍","상처로 균이 들어가 생깁니다.")],"모기 매개 = 말라리아·일본뇌염","**말라리아**와 일본뇌염은 **모기**가 옮기는 대표 감염병입니다.",4,["감염병"])
Q(C,'intermediate',"홍역을 앓고 나은 뒤 생긴 면역은?","자연능동면역",[("인공능동면역","예방접종으로 얻는 면역입니다."),("자연수동면역","엄마의 태반·모유로 받는 면역입니다."),("인공수동면역","면역 혈청 등을 주사해 얻는 면역입니다.")],"병을 앓고 생긴 면역 = 자연능동면역","병을 직접 앓고 나서 몸이 스스로 만든 면역은 **자연능동면역**입니다. 예방접종으로 얻으면 인공능동면역입니다.",4,["면역"])
Q(C,'intermediate',"독소형 세균성 식중독을 일으키며, 손의 상처 등에서 음식으로 옮는 균은?","황색포도상구균",[("살모넬라균","감염형 식중독의 원인균입니다."),("장염비브리오균","어패류로 생기는 감염형 식중독의 원인균입니다."),("결핵균","식중독 원인균이 아닙니다.")],"독소형 식중독 = 황색포도상구균","**황색포도상구균**은 손의 상처·고름 등에서 음식으로 옮아 독소를 만들어 식중독을 일으킵니다. 손에 상처가 있으면 조리를 피합니다.",3,["식품위생"])
Q(C,'basic',"세계보건기구(WHO)가 말하는 건강의 뜻으로 가장 알맞은 것은?","신체적·정신적·사회적으로 완전히 안녕한 상태",[("병이 없는 상태","병이 없는 것만으로는 건강의 뜻이 충분하지 않습니다."),("몸이 튼튼한 상태","신체만이 아니라 정신과 사회적 안녕까지 포함합니다."),("오래 사는 것","수명만으로 건강을 정의하지 않습니다.")],"WHO 건강 = 신체·정신·사회적 안녕","세계보건기구는 건강을 단지 질병이 없는 상태가 아니라 **신체적·정신적·사회적으로 완전히 안녕한 상태**라고 정의합니다.",4,["공중보건 기초"])

C='disinfection'
Q(C,'basic',"세균의 포자까지 포함해 모든 미생물을 죽이거나 없애는 것은?","멸균",[("소독","병원성 미생물을 죽이거나 약하게 하지만 포자까지 없애지는 못할 수 있습니다."),("방부","미생물이 늘어나는 것을 억제하는 것입니다."),("세척","더러운 것을 씻어 내는 것입니다.")],"포자까지 모두 = 멸균","**멸균**은 포자를 포함해 **모든 미생물**을 죽이거나 없애는 것으로 가장 강한 처리입니다. 소독력은 멸균 > 살균 > 소독 > 방부 순서입니다.",5,["소독 정의"])
Q(C,'basic',"공중위생관리법 시행규칙의 미용기구 소독기준에서 에탄올 소독에 쓰는 에탄올 수용액의 농도는?","70%",[("30%","너무 묽습니다."),("100%","소독기준의 농도가 아닙니다."),("3%","석탄산수·크레졸수의 농도입니다.")],"에탄올 소독 = 70% 에탄올 수용액","미용기구 소독기준의 **에탄올 소독**은 **70% 에탄올 수용액**에 10분 이상 담가 두거나, 이것을 머금은 솜·거즈로 기구 표면을 닦는 것입니다.",5,["미용기구 소독기준"])
Q(C,'intermediate',"미용기구 소독기준에서 열탕소독의 방법으로 알맞은 것은?","섭씨 100℃ 이상의 물속에 10분 이상 끓여 준다",[("섭씨 60℃의 물에 5분 담가 둔다","온도와 시간이 모두 모자랍니다."),("섭씨 100℃ 이상의 건조한 열에 20분 이상 쐬어 준다","건열멸균소독의 기준입니다."),("섭씨 100℃ 이상의 습한 열에 20분 이상 쐬어 준다","증기소독의 기준입니다.")],"열탕소독 = 100℃ 이상 물에 10분 이상","공중위생관리법 시행규칙의 미용기구 소독기준에서 **열탕소독**은 **섭씨 100℃ 이상의 물속에 10분 이상** 끓여 주는 것입니다. 건열멸균소독과 증기소독은 100℃ 이상에서 20분 이상입니다.",4,["미용기구 소독기준"])
Q(C,'intermediate',"미용기구 소독기준에서 자외선 소독의 방법으로 알맞은 것은?","1㎠당 85㎼ 이상의 자외선을 20분 이상 쬐어 준다",[("1㎠당 85㎼ 이상의 자외선을 1분 쬐어 준다","시간이 모자랍니다."),("햇볕에 반나절 말린다","소독기준의 방법이 아닙니다."),("형광등 아래에 하루 동안 둔다","소독기준의 방법이 아닙니다.")],"자외선 소독 = 1㎠당 85㎼ 이상, 20분 이상","미용기구 소독기준의 **자외선 소독**은 **1㎠당 85㎼ 이상**의 자외선을 **20분 이상** 쬐어 주는 것입니다.",4,["미용기구 소독기준"])
Q(C,'advanced',"공중위생관리법 시행규칙의 미용기구 소독기준으로 옳지 않은 것은?","크레졸 소독: 크레졸 30% 수용액에 1분 담가 둔다",[("석탄산수 소독: 석탄산 3% 수용액에 10분 이상 담가 둔다","옳은 기준입니다."),("에탄올 소독: 70% 에탄올 수용액에 10분 이상 담가 둔다","옳은 기준입니다."),("증기 소독: 100℃ 이상의 습한 열에 20분 이상 쐬어 준다","옳은 기준입니다.")],"석탄산수·크레졸수 = 3% 수용액에 10분 이상","소독기준에서 **크레졸 소독**은 **크레졸 3%, 물 97%**의 크레졸수에 **10분 이상** 담가 두는 것입니다. 석탄산수도 3% 수용액에 10분 이상입니다.",4,["미용기구 소독기준"],lock=True)
Q(C,'intermediate',"여러 소독약의 살균력을 비교할 때 기준으로 쓰는 약품은?","석탄산(페놀)",[("에탄올","소독약이지만 살균력 비교의 기준은 아닙니다."),("과산화수소","소독약이지만 비교 기준이 아닙니다."),("차아염소산나트륨","소독약이지만 비교 기준이 아닙니다.")],"살균력 비교 기준 = 석탄산","**석탄산(페놀)**은 살균력이 안정적이어서 다른 소독약의 살균력을 비교하는 기준(석탄산 계수)으로 쓰입니다.",4,["화학적 소독"])
Q(C,'basic',"미생물이 늘어나는 것을 억제해 물건이 썩거나 변질되지 않게 하는 것은?","방부",[("멸균","모든 미생물을 없애는 것입니다."),("살균","미생물을 죽이는 것입니다."),("세척","씻어 내는 것입니다.")],"미생물 증식 억제 = 방부","**방부**는 미생물을 죽이지는 않더라도 **늘어나는 것을 억제**해 썩거나 변질되는 것을 막는 것입니다. 화장품의 방부제가 그 예입니다.",4,["소독 정의"])
Q(C,'intermediate',"바이러스에 대한 설명으로 옳은 것은?","살아 있는 세포 안에서만 증식한다",[("스스로 영양분을 만들어 증식한다","바이러스는 스스로 증식하지 못합니다."),("세균보다 크기가 훨씬 크다","바이러스는 세균보다 훨씬 작습니다."),("항생제로 쉽게 죽는다","항생제는 세균에 쓰는 약으로 바이러스에는 듣지 않습니다.")],"바이러스 = 살아 있는 세포 안에서만 증식","**바이러스**는 세균보다 훨씬 작고, 스스로 증식하지 못해 **살아 있는 세포 안에서만** 증식합니다. 항생제가 듣지 않습니다.",3,["미생물"])
Q(C,'basic',"네일숍에서 메탈 푸셔·니퍼 같은 금속 도구의 위생 관리로 가장 알맞은 것은?","고객마다 씻은 뒤 소독하고, 소독한 도구는 따로 보관한다",[("하루 일을 마칠 때 한 번만 소독한다","고객마다 소독해야 합니다."),("눈에 띄는 때만 휴지로 닦는다","닦는 것만으로는 소독이 되지 않습니다."),("소독한 도구와 쓴 도구를 한 통에 함께 둔다","섞이면 다시 오염됩니다.")],"도구 = 고객마다 세척·소독, 따로 보관","금속 도구는 **고객마다** 씻어서 이물을 없앤 뒤 소독하고, 소독한 도구와 쓴 도구를 **구분해 보관**합니다.",4,["분야별 위생·소독"])

C='hygiene-law'
Q(C,'basic',"미용사(네일) 자격을 따고 미용사 면허를 받은 사람이 할 수 있는 업무는?","손톱과 발톱의 손질 및 화장",[("머리카락 자르기와 파마","미용사(일반)의 업무입니다."),("의료기기를 쓰지 않는 피부관리","미용사(피부)의 업무입니다."),("얼굴 메이크업","미용사(메이크업)의 업무입니다.")],"미용사(네일) 업무 = 손톱·발톱의 손질 및 화장","공중위생관리법 시행규칙에서 미용사(네일)의 업무범위는 **손톱과 발톱의 손질 및 화장**입니다.",5,["업무범위"])
Q(C,'basic',"미용업을 폐업한 사람은 폐업한 날부터 며칠 이내에 시장·군수·구청장에게 신고해야 하는가?","20일",[("7일","기한이 다릅니다."),("30일","기한이 다릅니다."),("3개월","기한이 다릅니다.")],"폐업신고 = 폐업한 날부터 20일 이내","공중위생관리법에 따라 공중위생영업자는 폐업한 날부터 **20일 이내**에 시장·군수·구청장에게 신고해야 합니다.",5,["영업의 신고 및 폐업"])
Q(C,'basic',"공중위생영업자가 매년 받아야 하는 위생교육의 시간은?","3시간",[("1시간","시간이 다릅니다."),("8시간","시간이 다릅니다."),("12시간","시간이 다릅니다.")],"위생교육 = 매년 3시간","공중위생영업자는 **매년 3시간**의 위생교육을 받아야 합니다.",5,["위생교육"])
Q(C,'intermediate',"공중위생영업소의 위생서비스수준 평가는 원칙적으로 몇 년마다 실시하는가?","2년",[("1년","주기가 다릅니다."),("3년","주기가 다릅니다."),("5년","주기가 다릅니다.")],"위생서비스평가 = 2년마다","시장·군수·구청장은 공중위생영업소의 위생서비스수준을 원칙적으로 **2년마다** 평가합니다.",4,["업소 위생등급"])
Q(C,'intermediate',"위생서비스평가 결과 최우수업소에 주어지는 위생관리등급은?","녹색등급",[("황색등급","우수업소의 등급입니다."),("백색등급","일반관리대상 업소의 등급입니다."),("적색등급","위생관리등급에 없는 등급입니다.")],"최우수 = 녹색, 우수 = 황색, 일반관리 = 백색","위생관리등급은 **최우수업소 녹색등급**, 우수업소 황색등급, 일반관리대상 업소 백색등급입니다.",4,["업소 위생등급"])
Q(C,'basic',"미용사 면허를 내주는 사람은?","시장·군수·구청장",[("보건복지부장관","면허를 직접 내주지 않습니다."),("한국산업인력공단 이사장","자격시험을 시행하는 기관입니다."),("시·도 교육감","미용사 면허와 관계없습니다.")],"미용사 면허 = 시장·군수·구청장","미용사가 되려면 자격을 딴 뒤 **시장·군수·구청장**에게 면허를 받아야 합니다.",4,["면허"])
Q(C,'intermediate',"미용사 면허를 받지 않고 미용업을 열거나 미용 업무를 한 사람에 대한 벌칙은?","300만원 이하의 벌금",[("1년 이하의 징역 또는 1천만원 이하의 벌금","영업신고를 하지 않고 영업한 경우 등의 벌칙입니다."),("과태료 10만원","벌칙이 다릅니다."),("벌칙 없이 경고만 한다","벌칙이 있습니다.")],"면허 없이 미용 업무 = 300만원 이하 벌금","공중위생관리법에 따라 **면허 없이** 미용업을 개설하거나 미용 업무를 한 사람은 **300만원 이하의 벌금**에 처합니다.",4,["벌칙"])
Q(C,'advanced',"미용사가 영업소 밖에서 미용 업무를 할 수 있는 경우가 아닌 것은?","손님이 가게보다 집이 편하다며 와 달라고 원하는 경우",[("질병 등으로 영업소에 나올 수 없는 사람에게 하는 경우","영업소 밖에서 할 수 있는 경우입니다."),("혼례 등 의식 직전에 하는 경우","영업소 밖에서 할 수 있는 경우입니다."),("방송 촬영에 참여하는 사람에게 촬영 직전에 하는 경우","영업소 밖에서 할 수 있는 경우입니다.")],"영업소 밖 미용 = 질병·의식 직전·사회복지시설 봉사·촬영 직전 등","미용 업무는 원칙적으로 **영업소 안에서만** 합니다. 질병 등으로 나올 수 없는 사람, 혼례 등 의식 직전, 사회복지시설 봉사, 방송 촬영 직전 등 특별한 경우만 영업소 밖에서 할 수 있습니다. 손님이 편하다는 이유만으로는 안 됩니다.",4,["영업자 준수사항"],lock=True)
Q(C,'advanced',"미용사가 면허증을 다른 사람에게 빌려준 경우 1차 위반의 행정처분 기준은?","면허정지 3월",[("면허정지 6월","2차 위반의 처분입니다."),("면허취소","3차 위반의 처분입니다."),("경고","1차 위반의 처분이 아닙니다.")],"면허증 대여: 1차 정지 3월 → 2차 정지 6월 → 3차 취소","공중위생관리법 시행규칙의 행정처분기준에서 **면허증을 다른 사람에게 대여**한 경우는 1차 위반 **면허정지 3월**, 2차 위반 면허정지 6월, 3차 위반 면허취소입니다.",3,["행정처분"])
